do $$
declare
  seed_row record;
  source_uuid uuid;
  category_uuid uuid;
  parent_category_uuid uuid;
begin
  if not exists (
    select 1 from public.sources where code = 'uniqlo'
  ) then
    raise exception
      'Required Uniqlo source is missing. Run fitmatch_supabase_seed_sources.sql first.';
  end if;

  if (select count(*) from _fitmatch_source_category_seed) <> 1717 then
    raise exception 'Uniqlo seed input validation failed: expected 1717 rows.';
  end if;

  if (select count(*) from _fitmatch_source_category_seed where (metadata ->> 'is_leaf')::boolean) <> 1495 then
    raise exception 'Uniqlo seed input validation failed: expected 1495 leaf rows.';
  end if;

  if exists (
    select 1 from _fitmatch_source_category_seed as seed_data
    where seed_data.source_code <> 'uniqlo'
  ) then
    raise exception 'Uniqlo seed input validation failed: non-Uniqlo row found.';
  end if;

  if (select count(*) from _fitmatch_source_category_seed where audience = 'MEN') <> 570
     or (select count(*) from _fitmatch_source_category_seed where audience = 'WOMEN') <> 823
     or (select count(*) from _fitmatch_source_category_seed where audience = 'KIDS') <> 237
     or (select count(*) from _fitmatch_source_category_seed where audience = 'BABY') <> 87 then
    raise exception 'Uniqlo seed input validation failed: audience counts differ.';
  end if;

  for seed_row in
    select seed_data.*
    from _fitmatch_source_category_seed as seed_data
    order by seed_data.source_code, coalesce(seed_data.audience, ''),
             seed_data.depth, seed_data.external_category_id
  loop
    select source_row.id
      into source_uuid
    from public.sources as source_row
    where source_row.code = seed_row.source_code;

    parent_category_uuid := null;
    if seed_row.parent_external_category_id is not null then
      select parent_row.id
        into parent_category_uuid
      from public.source_categories as parent_row
      where parent_row.source_id = source_uuid
        and parent_row.brand_id is null
        and coalesce(parent_row.audience, '') = coalesce(seed_row.audience, '')
        and parent_row.external_category_id = seed_row.parent_external_category_id;

      if parent_category_uuid is null then
        raise exception
          'Missing parent source category: source=%, audience=%, parent_external_id=%',
          seed_row.source_code,
          seed_row.audience,
          seed_row.parent_external_category_id;
      end if;
    end if;

    category_uuid := null;
    select category_row.id
      into category_uuid
    from public.source_categories as category_row
    where category_row.source_id = source_uuid
      and category_row.brand_id is null
      and coalesce(category_row.audience, '') = coalesce(seed_row.audience, '')
      and category_row.external_category_id = seed_row.external_category_id
    order by category_row.created_at
    limit 1;

    if category_uuid is null then
      select sample_row.id
        into category_uuid
      from public.source_categories as sample_row
      where sample_row.source_id = source_uuid
        and sample_row.brand_id is null
        and coalesce(sample_row.audience, '') = coalesce(seed_row.audience, '')
        and sample_row.external_category_id is null
        and sample_row.original_path = seed_row.original_path
      order by sample_row.created_at
      limit 1;
    end if;

    if category_uuid is null then
      insert into public.source_categories (
        source_id,
        brand_id,
        parent_id,
        external_category_id,
        name,
        original_path,
        audience,
        depth,
        app_category,
        app_detail_category,
        metadata,
        is_active
      )
      values (
        source_uuid,
        null,
        parent_category_uuid,
        seed_row.external_category_id,
        seed_row.name,
        seed_row.original_path,
        seed_row.audience,
        seed_row.depth,
        seed_row.app_category,
        seed_row.app_detail_category,
        seed_row.metadata,
        true
      );
    else
      update public.source_categories as category_row
      set
        parent_id = parent_category_uuid,
        external_category_id = seed_row.external_category_id,
        name = seed_row.name,
        original_path = seed_row.original_path,
        audience = seed_row.audience,
        depth = seed_row.depth,
        app_category = seed_row.app_category,
        app_detail_category = seed_row.app_detail_category,
        metadata = case
          when seed_row.audience in ('WOMEN', 'KIDS', 'BABY')
            then (category_row.metadata || seed_row.metadata) - 'evidence_url'
          else category_row.metadata || seed_row.metadata
        end,
        is_active = true,
        updated_at = now()
      where category_row.id = category_uuid;
    end if;
  end loop;

  update public.source_categories as category_row
  set
    is_active = false,
    updated_at = now(),
    metadata = category_row.metadata || jsonb_build_object(
      'inactive_since_snapshot_date', '2026-07-26'
    )
  where category_row.metadata ->> 'managed_by' = 'fitmatch_source_catalog_full_seed'
    and exists (
      select 1
      from public.sources as source_row
      where source_row.id = category_row.source_id
        and source_row.code = 'uniqlo'
    )
    and not exists (
      select 1
      from _fitmatch_source_category_seed as seed_data
      join public.sources as source_row on source_row.code = seed_data.source_code
      where source_row.id = category_row.source_id
        and coalesce(seed_data.audience, '') = coalesce(category_row.audience, '')
        and seed_data.external_category_id = category_row.external_category_id
    );

  if (
    select count(*)
    from public.source_categories as category_row
    join public.sources as source_row on source_row.id = category_row.source_id
    join _fitmatch_source_category_seed as seed_data
      on seed_data.source_code = source_row.code
     and coalesce(seed_data.audience, '') = coalesce(category_row.audience, '')
     and seed_data.external_category_id = category_row.external_category_id
    where source_row.code = 'uniqlo'
      and category_row.brand_id is null
      and category_row.is_active
      and category_row.metadata ->> 'managed_by' = 'fitmatch_source_catalog_full_seed'
  ) <> 1717 then
    raise exception 'Uniqlo source-category seed validation failed: expected 1717 active managed rows.';
  end if;

  if exists (
    select 1
    from public.source_categories as category_row
    join public.sources as source_row on source_row.id = category_row.source_id
    join _fitmatch_source_category_seed as seed_data
      on seed_data.source_code = source_row.code
     and coalesce(seed_data.audience, '') = coalesce(category_row.audience, '')
     and seed_data.external_category_id = category_row.external_category_id
    where source_row.code = 'uniqlo'
      and (seed_data.metadata ->> 'is_leaf')::boolean
      and (category_row.app_category is null or category_row.app_detail_category is null)
  ) then
    raise exception 'Uniqlo source-category seed validation failed: a leaf mapping is missing.';
  end if;
end
$$;

commit;

-- 1. Uniqlo total managed rows. Expected: 1717.
select count(*) as uniqlo_total_managed_rows
from public.source_categories as category_row
join public.sources as source_row on source_row.id = category_row.source_id
where source_row.code = 'uniqlo'
  and category_row.metadata ->> 'managed_by' = 'fitmatch_source_catalog_full_seed';

-- 2. Active managed rows. Expected: 1717.
select count(*) as uniqlo_active_managed_rows
from public.source_categories as category_row
join public.sources as source_row on source_row.id = category_row.source_id
where source_row.code = 'uniqlo'
  and category_row.metadata ->> 'managed_by' = 'fitmatch_source_catalog_full_seed'
  and category_row.is_active;

-- 3. Leaf rows. Expected: 1495.
select count(*) as uniqlo_leaf_rows
from public.source_categories as category_row
join public.sources as source_row on source_row.id = category_row.source_id
where source_row.code = 'uniqlo'
  and category_row.metadata ->> 'managed_by' = 'fitmatch_source_catalog_full_seed'
  and (category_row.metadata ->> 'is_leaf')::boolean;

-- 4. Audience row counts. Expected: MEN 570, WOMEN 823, KIDS 237, BABY 87.
select category_row.audience, count(*) as managed_rows
from public.source_categories as category_row
join public.sources as source_row on source_row.id = category_row.source_id
where source_row.code = 'uniqlo'
  and category_row.metadata ->> 'managed_by' = 'fitmatch_source_catalog_full_seed'
group by category_row.audience
order by category_row.audience;

-- 5. Musinsa rows included in this Uniqlo catalog scope. Expected: 0.
select count(*) as musinsa_included_rows
from public.source_categories as category_row
join public.sources as source_row on source_row.id = category_row.source_id
where source_row.code = 'musinsa'
  and category_row.metadata ->> 'catalog_scope' = 'uniqlo_kr_taxonomy_payload_all_audiences';

-- 6. Duplicate external_category_id groups. Expected: 0.
select count(*) as duplicate_external_category_id_groups
from (
  select category_row.audience, category_row.external_category_id
  from public.source_categories as category_row
  join public.sources as source_row on source_row.id = category_row.source_id
  where source_row.code = 'uniqlo'
    and category_row.metadata ->> 'managed_by' = 'fitmatch_source_catalog_full_seed'
    and category_row.external_category_id is not null
  group by category_row.audience, category_row.external_category_id
  having count(*) > 1
) as duplicate_ids;

-- 7. Duplicate original_path groups within one audience.
select count(*) as duplicate_original_path_groups
from (
  select category_row.audience, category_row.original_path
  from public.source_categories as category_row
  join public.sources as source_row on source_row.id = category_row.source_id
  where source_row.code = 'uniqlo'
    and category_row.metadata ->> 'managed_by' = 'fitmatch_source_catalog_full_seed'
  group by category_row.audience, category_row.original_path
  having count(*) > 1
) as duplicate_paths;

-- 8. Orphan parent_id rows. Expected: 0.
select count(*) as orphan_parent_rows
from public.source_categories as category_row
join public.sources as source_row on source_row.id = category_row.source_id
left join public.source_categories as parent_row on parent_row.id = category_row.parent_id
where source_row.code = 'uniqlo'
  and category_row.metadata ->> 'managed_by' = 'fitmatch_source_catalog_full_seed'
  and category_row.parent_id is not null
  and parent_row.id is null;

-- 9. Incorrect MEN evidence_url remaining on WOMEN/KIDS/BABY rows. Expected: 0.
select count(*) as incorrect_men_evidence_url_rows
from public.source_categories as category_row
join public.sources as source_row on source_row.id = category_row.source_id
where source_row.code = 'uniqlo'
  and category_row.metadata ->> 'managed_by' = 'fitmatch_source_catalog_full_seed'
  and category_row.audience in ('WOMEN', 'KIDS', 'BABY')
  and category_row.metadata ->> 'evidence_url' = 'https://www.uniqlo.com/kr/ko/men';
